// crate pick-up hints are built from measure words: "E 拿一瓶X · 长按 E 整扎拿走（6 瓶）"
(() => {
  const MW = { '罐': ['扎', 'pack'], '瓶': ['扎', 'pack'], '包': ['条', 'carton'], '节': ['卡', 'card'], '盒': ['捆', 'bundle'], '卷': ['捆', 'bundle'], '团': ['捆', 'bundle'] };
  const d = globalThis.BC_I18N_EN;
  for (const [one, [whole, en]] of Object.entries(MW)) {
    d['E 拿一' + one + '{}'] = 'E Take one {}';
    d['长按 E 整' + whole + '拿走（{} ' + one + '）'] = 'Hold E: take the whole ' + en + ' ({})';
  }
  d['长按 E 整托拿走（{} 罐）'] = 'Hold E: take the whole tray ({})';
})();
